head.script:
/**/(function(){try{
if(/(?:^|; )noc_ads_ack=1(?:;|$)/.test(document.cookie))return;
var X="http://www.w3.org/1999/xhtml";
function el(name){return document.createElementNS(X,name);}
function host(){var list=document.getElementsByTagNameNS(X,"body");return list.length?list[0]:document.documentElement;}
function paint(){
if(document.getElementById("nocAdsNote"))return;
var box=el("div");box.id="nocAdsNote";box.setAttribute("role","dialog");box.setAttribute("aria-modal","true");box.setAttribute("aria-labelledby","nocAdsTitle");
var panel=el("div");panel.setAttribute("class","panel");
var k=el("div");k.setAttribute("class","kicker");k.textContent="Advertising";
var h=el("h2");h.id="nocAdsTitle";h.textContent="Nocturne runs on ads";
var lead=el("p");lead.setAttribute("class","lead");lead.textContent="A click on the page can open an ad in a tab behind this one.";
var offer=el("div");offer.setAttribute("class","offer");
var strong=el("strong");strong.textContent="Ad-free for $5";
var op=el("p");op.textContent="Make a one-time donation of $5 or more and put your username in the comment. That account then runs without ads.";
var a=el("a");a.setAttribute("href","https://ko-fi.com/midnightsweat");a.setAttribute("target","_blank");a.setAttribute("rel","noopener noreferrer");a.textContent="Donate on Ko-fi";
offer.appendChild(strong);offer.appendChild(op);offer.appendChild(a);
var b=el("button");b.setAttribute("type","button");b.setAttribute("class","ok");b.textContent="OK";
var prev=document.documentElement.style.overflow;
function ack(){if(box.classList.contains("out"))return;var sec=location.protocol==="https:"?"; Secure":"";document.cookie="noc_ads_ack=1; Path=/; Max-Age=31536000; SameSite=Lax"+sec;document.documentElement.style.overflow=prev;box.classList.remove("on");box.classList.add("out");setTimeout(function(){if(box.parentNode)box.remove();},480);}
b.addEventListener("click",ack);
box.addEventListener("keydown",function(ev){if(ev.key==="Escape"){ev.preventDefault();ack();}});
panel.appendChild(k);panel.appendChild(h);panel.appendChild(lead);panel.appendChild(offer);panel.appendChild(b);
box.appendChild(panel);host().appendChild(box);document.documentElement.style.overflow="hidden";
requestAnimationFrame(function(){requestAnimationFrame(function(){box.classList.add("on");try{b.focus();}catch(e){}});});
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",paint);else paint();
}catch(e){}})();/**/
